import Atomics

// A real-time ring for an audio render callback: no allocation, no locks.
final class AudioRing {
    private let buf: UnsafeMutablePointer<Float>   // preallocated once
    private let capacity: Int                      // a power of two
    private let mask: Int
    private let head = ManagedAtomic<Int>(0)       // producer (render thread)
    private let tail = ManagedAtomic<Int>(0)       // consumer (main thread)

    // push (render callback): write, then release-store the head.
    func push(_ v: Float) -> Bool {
        let h = head.load(ordering: .relaxed)
        if h &- tail.load(ordering: .acquiring) == capacity { return false }  // full
        buf[h & mask] = v
        head.store(h &+ 1, ordering: .releasing)     // release: item before head
        return true
    }
    // ... pop mirrors it: acquire the head, read, release the tail ...
    deinit { buf.deallocate() }
}
